private class OpportunityCleanupServiceTest {

    @IsTest
    static void testCloseStale_nullOrEmptyIds() {
        Test.startTest();
        Integer resultNull = OpportunityCleanupService.closeStale(null, Date.today());
        Integer resultEmpty = OpportunityCleanupService.closeStale(new Set<Id>(), Date.today());
        Test.stopTest();

        System.assertEquals(0, resultNull, 'Should return 0 for null ids');
        System.assertEquals(0, resultEmpty, 'Should return 0 for empty ids');
    }

    @IsTest
    static void testCloseStale_mixedRecords() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();

        IOpportunitiesSelector mockSelector = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        fflib_ISObjectUnitOfWork mockUow = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);

        Id id1 = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id id2 = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id id3 = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id id4 = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id id5 = fflib_IDGenerator.generate(Opportunity.SObjectType);

        Date cutoff = Date.newInstance(2024, 1, 1);

        List<Opportunity> mockOpps = new List<Opportunity>{
            new Opportunity(Id = id1, StageName = 'Prospecting', CloseDate = cutoff.addDays(-1)), // stale
            new Opportunity(Id = id2, StageName = 'Closed Won', CloseDate = cutoff.addDays(-1)),  // ignored (Closed Won)
            new Opportunity(Id = id3, StageName = 'Prospecting', CloseDate = cutoff),             // ignored (on cutoff)
            new Opportunity(Id = id4, StageName = 'Prospecting', CloseDate = null),               // ignored (null date)
            new Opportunity(Id = id5, StageName = 'Negotiation', CloseDate = cutoff.addDays(-5))  // stale
        };

        mocks.startStubbing();
        mocks.when(mockSelector.sObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.when(mockSelector.selectById((Set<Id>) fflib_Match.anyObject())).thenReturn(mockOpps);
        mocks.stopStubbing();

