public inherited sharing class Accounts extends fflib_SObjects implements IAccounts {

    public static IAccounts newInstance(List<Account> records) {
        return (IAccounts) Application.Domain.newInstance(records);
    }

    public static IAccounts newInstance(Set<Id> accountIds) {
        return (IAccounts) Application.Domain.newInstance(accountIds);
    }

    public Accounts(List<Account> records) {
        super(records, Account.SObjectType);
    }

    public override Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Account> getAccounts() {
        return (List<Account>) getRecords();
    }

    public IAccounts selectByRating(String rating) {
        List<Account> matchingRecords = new List<Account>();
        for (Account acc : getAccounts()) {
            if (acc.Rating == rating) {
                matchingRecords.add(acc);
            }
        }
        return newInstance(matchingRecords);
    }

    public Set<Id> getOwnerIds() {
        Set<Id> ownerIds = new Set<Id>();
        for (Account acc : getAccounts()) {
            if (acc.OwnerId != null) {
                ownerIds.add(acc.OwnerId);
            }
        }
        return ownerIds;
    }

    public void setRating(String rating) {
        for (Account acc : getAccounts()) {
            acc.Rating = rating;
        }
    }

    public class Constructor implements fflib_IDomainConstructor {
        public fflib_ISObjects construct(List<Object> records) {
            return new Accounts((List<Account>) records);
        }
    }
}
