public class Opportunities extends fflib_SObjectDomain {

    public Opportunities(List<Opportunity> sObjectList) {
        super(sObjectList);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }

    public override void onValidate() {
        for (Opportunity opp : (List<Opportunity>) Records) {
            if (opp.Amount != null && opp.Amount < 0) {
                opp.addError(Opportunity.Amount, 'Amount cannot be negative.');
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }
    }

    public override void onValidate(Map<Id, SObject> existingRecords) {
        for (Opportunity opp : (List<Opportunity>) Records) {
            if (opp.Amount != null && opp.Amount < 0) {
                opp.addError(Opportunity.Amount, 'Amount cannot be negative.');
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }

            Opportunity oldOpp = (Opportunity) existingRecords.get(opp.Id);
            if (oldOpp != null && oldOpp.StageName == 'Closed Won' && opp.Amount != oldOpp.Amount) {
                opp.addError(Opportunity.Amount, 'Amount cannot change on a won opportunity.');
                error('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
            }
        }
    }
}
